import{_ as o,c as a,o as s,ae as c}from"./chunks/framework.DEXG3EuZ.js";const u=JSON.parse('{"title":"リクエストと認証","description":"","frontmatter":{},"headers":[],"relativePath":"ja/guide/request.md","filePath":"ja/guide/request.md","lastUpdated":1792605191000}'),d={name:"ja/guide/request.md"};function t(i,e,p,r,n,l){return s(),a("div",null,[...e[0]||(e[0]=[c(`<h1 id="リクエストと認証" tabindex="-1">リクエストと認証 <a class="header-anchor" href="#リクエストと認証" aria-label="Permalink to &quot;リクエストと認証&quot;">​</a></h1><p>ページから Axios を直接 import せず、<code>src/api/modules</code> の Domain 関数を使います。JSON API は <code>ApiResponse&lt;T&gt;</code> を展開し、失敗は <code>ApiError</code> に正規化します。Token と任意の Request ID は Request Interceptor が追加します。</p><p>HTTP、Business Error、401、Timeout、Network、Cancel を区別します。401 は Session を削除し、安全な内部 Redirect だけを Login に渡します。</p><p>契約変更時：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> api:generate</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> typecheck</span></span></code></pre></div><p><code>openapi/schema.yaml</code> と生成済み <code>src/types/api/generated.d.ts</code> を同時に Commit します。</p><h2 id="rest-契約とキャンセル" tabindex="-1">REST 契約とキャンセル <a class="header-anchor" href="#rest-契約とキャンセル" aria-label="Permalink to &quot;REST 契約とキャンセル&quot;">​</a></h2><p>単体アプリの通信層は、実サービスの <code>code: 0</code>／<code>message</code> と旧 Mock の 2xx 業務コード／<code>msg</code> に対応します。いずれも <code>data</code> を返し、失敗は <code>ApiError</code> です。HTTP 2xx だけで業務の成功を判定しません。</p><p>以下の関数は包装を外したデータを返し、失敗は <code>ApiError</code> として通知します。取得には Query の <code>AbortSignal</code> を渡します。更新には起動時に設定した認証クライアントを使い、呼び出し側から所有者 ID を送信しません。</p><p>単体アプリでは <code>VITE_AI_API_BASE_URL</code>（既定 <code>/api/ai</code>）で提案を取得し、開発プロキシを <code>VITE_AI_API_TARGET</code> で指定します。通常の業務通信は Gin に送ります。JSON は <code>src/api/modules/ai.ts</code>、ストリーミングはプロバイダーと composable が担当します。</p><p>応答の包装への対応は、パスや商品フィールドの変換を意味しません。単体アプリの商品 API は <code>/api/products</code> と多言語 <code>name</code>／<code>priceCents</code>、現在の Gin は <code>/api/product/list</code> と <code>title</code>／<code>price</code> です。ログインにも <code>name</code>／<code>token</code> と <code>username</code>／<code>accessToken</code> の差があります。全面的な連携を確認する前に契約を照合するか、明示的なドメインアダプターを追加してください。新しいお気に入りパスは Gin に一致しますが、認証には互換性のある発行済み JWT が必要です。</p>`,11)])])}const m=o(d,[["render",t]]);export{u as __pageData,m as default};
